{
  "ledger": [
    {
      "id": "H1",
      "type": "power_failure",
      "component": ["gpu-4", "gpu-5", "gpu-6"],
      "setting": null,
      "explains": [
        "down:replica-4",
        "unreachable:gpu-4",
        "unreachable:gpu-5",
        "unreachable:gpu-6"
      ],
      "evidence": [
        "BMC reports PSU fault on rack-b for gpu-4, gpu-5, gpu-6",
        "All affected GPUs are in rack-b",
        "Telemetry (temp/clock) reads 0, indicating hardware power loss"
      ],
      "status": "suspected",
      "confidence": 0.95
    }
  ],
  "actions": [
    {
      "action": "drain",
      "args": {
        "node": "gpu-4"
      },
      "hypothesis": "H1",
      "purpose": "fix",
      "why": "Move replica-4 to a healthy node to restore service capacity, as gpu-4 is powered off."
    },
    {
      "action": "set_weight",
      "args": {
        "replica": "replica-4",
        "weight": 0
      },
      "hypothesis": "H1",
      "purpose": "fix",
      "why": "Stop sending traffic to the down replica immediately."
    },
    {
      "action": "escalate",
      "args": {
        "team": "infrastructure-hardware",
        "summary": "Rack-b power failure affecting GPUs 4, 5, and 6. BMC reports PSU faults. All telemetry lost. Replica-4 is down. Hardware team needed to replace PSU or repair rack-b power supply."
      },
      "hypothesis": "H1",
      "purpose": "escalate",
      "why": "This is a hardware/power issue outside the scope of software configuration changes."
    }
  ],
  "summary": "Identified a power failure in rack-b affecting GPUs 4, 5, and 6 based on BMC logs; drained the affected node and escalated to infrastructure hardware team."
}
